/* ===== Việc tiếp theo từ kết quả này (V2.91) =====
     Việc đã có kết quả thì ngay trong chi tiết có một khu để giao việc kế tiếp: anh nói (mic) hoặc gõ điều muốn làm tiếp, bảng gói kết quả
     việc trước (tóm tắt, các phần đã làm, thư mục trong bộ não) làm đầu vào rồi giao như một việc mới. Đội làm nối tiếp, không làm lại từ đầu. */
  function vtCoKetQua(r){return !r.demo&&!r.local&&((r.plan||[]).some(function(p){return /^(done|given|duyet)$/.test(p.state||'')&&p.out;})||!!String(r.summary||'').trim());}
  function vtHtml(r,canAct){
    if(!canAct||!vtCoKetQua(r))return '';
    var chips=['Viết 30 bài content từ kết quả này','Lên kịch bản 5 video ngắn từ phát hiện chính','Soạn chiến dịch quảng cáo từ kết quả này','Làm trang bán hàng từ kết quả này','Tóm tắt 1 trang để anh duyệt rồi làm tiếp'];
    return '<section class="zone zone-next" id="vt-box" data-vt="'+esc(r.id)+'"><div class="zone-label">Việc tiếp theo từ kết quả này</div>'+
      '<p class="sub" style="margin:0 0 8px">Nói hoặc gõ việc kế tiếp anh muốn làm. '+esc(TAM_SHORT)+' lấy kết quả của việc này làm đầu vào và làm nối tiếp, không làm lại từ đầu.</p>'+
      '<div class="rv-chips">'+chips.map(function(c){return '<button type="button" class="chip" data-vt-chip>'+esc(c)+'</button>';}).join('')+'</div>'+
      '<textarea id="vt-ta" rows="3" maxlength="1500" placeholder="Ví dụ: Từ các nỗi đau này, viết 30 content Fanpage theo 5 tuần, mỗi tuần 6 bài. Giọng gần gũi, hợp người mới."></textarea>'+
      '<div class="row-actions" style="margin-top:8px"><button type="button" class="btn btn-primary" data-vt-giao><span data-ico="send"></span>Giao việc tiếp</button><span class="sub" id="vt-tt" style="align-self:center"></span></div></section>';}
  function vtGoi(r,yc){
    var L=['VIỆC TIẾP THEO, làm nối tiếp việc đã xong.','Việc trước: "'+String(r.title||'').slice(0,160)+'" ('+fmtDay(r.date)+' '+(r.time||'')+').'];
    if(r.folder)L.push('Kết quả việc trước nằm trong bộ não, thư mục: '+r.folder+' . Đọc các file ở đó trước khi làm.');
    var sum=String(r.summary||'').replace(/\s+/g,' ').trim().slice(0,900);if(sum)L.push('Tóm tắt kết quả việc trước: '+sum);
    var ph=(r.plan||[]).filter(function(p){return p.out;}).slice(0,6).map(function(p){return '- '+agentName(p.agent)+': '+String(p.viec||'').slice(0,80)+' => '+String(p.out).replace(/\s+/g,' ').slice(0,260);});
    if(ph.length)L.push('Các phần đã làm:\n'+ph.join('\n'));
    L.push('YÊU CẦU MỚI CỦA '+String(OWNER_REF||'anh').toUpperCase()+': '+yc);
    L.push('Cách làm: dùng kết quả việc trước làm đầu vào, KHÔNG làm lại từ đầu, nói rõ đã lấy gì từ kết quả cũ. Thiếu thông tin quan trọng thì hỏi lại ngắn gọn.');
    return L.join('\n').slice(0,4900);}
  document.addEventListener('click',function(e){
    var c=e.target.closest&&e.target.closest('[data-vt-chip]');
    if(c){var ta=document.getElementById('vt-ta');if(ta){ta.value=c.textContent;ta.focus();}return;}
    var g=e.target.closest&&e.target.closest('[data-vt-giao]');if(!g)return;
    var box=g.closest('#vt-box'),r=box&&findResult(box.getAttribute('data-vt')),t=document.getElementById('vt-ta'),tt=document.getElementById('vt-tt');
    if(!r)return;var yc=String((t&&t.value)||'').trim();
    if(yc.length<6){if(tt)tt.textContent='Anh nói hoặc gõ việc kế tiếp trước nhé.';if(t)t.focus();return;}
    var text=vtGoi(r,yc);
    try{Drawer.close();}catch(x){}
    go('ban-lam-viec');var ta2=$('#demo-input');ta2.value=text;ta2.dispatchEvent(new Event('input'));
    setTimeout(function(){var rb=$('#demo-run');if(rb)rb.click();},350);
    try{toast('Đã giao việc tiếp. Đội nhận kết quả việc trước làm đầu vào.');}catch(x){}
  });
